// a builder and applies setFunc on it.
func (c *NillableWidgetClient) MapCreateBulk(slice any, setFunc func(*NillableWidgetCreate, int)) *NillableWidgetCreateBulk {
	rv := reflect.ValueOf(slice)
	if rv.Kind() != reflect.Slice {
		return &NillableWidgetCreateBulk{err: fmt.Errorf("calling to NillableWidgetClient.MapCreateBulk with wrong type %T, need slice", slice)}
	}
	builders := make([]*NillableWidgetCreate, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		builders[i] = c.Create()
		setFunc(builders[i], i)
	}
	return &NillableWidgetCreateBulk{config: c.config, builders: builders}
}

