// DeleteOneID returns a builder for deleting the given entity by its id.
func (c *NillableWidgetClient) DeleteOneID(id uuid.UUID) *NillableWidgetDeleteOne {
	builder := c.Delete().Where(nillablewidget.ID(id))
	builder.mutation.id = &id
	builder.mutation.op = OpDeleteOne
	return &NillableWidgetDeleteOne{builder}
}

