// Get returns a NillableWidget entity by its id.
func (c *NillableWidgetClient) Get(ctx context.Context, id uuid.UUID) (*NillableWidget, error) {
	return c.Query().Where(nillablewidget.ID(id)).Only(ctx)
}

// GetX is like Get, but panics if an error occurs.
func (c *NillableWidgetClient) GetX(ctx context.Context, id uuid.UUID) *NillableWidget {
	obj, err := c.Get(ctx, id)
	if err != nil {
		panic(err)
	}
	return obj
}

// Hooks returns the client hooks.
func (c *NillableWidgetClient) Hooks() []Hook {
	return c.hooks.NillableWidget
}

// Interceptors returns the client interceptors.
func (c *NillableWidgetClient) Interceptors() []Interceptor {
	return c.inters.NillableWidget
}

func (c *NillableWidgetClient) mutate(ctx context.Context, m *NillableWidgetMutation) (Value, error) {
	switch m.Op() {
	case OpCreate:
		return (&NillableWidgetCreate{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpUpdate:
		return (&NillableWidgetUpdate{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpUpdateOne:
		return (&NillableWidgetUpdateOne{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpDelete, OpDeleteOne:
		return (&NillableWidgetDelete{config: c.config, hooks: c.Hooks(), mutation: m}).Exec(ctx)
	default:
		return nil, fmt.Errorf("ent: unknown NillableWidget mutation op: %q", m.Op())
	}
}

// hooks and interceptors per client, for fast access.
type (
	hooks struct {
		EnumWidget, JSONWidget, NamedTypeWidget, NillableWidget []ent.Hook
	}
	inters struct {
		EnumWidget, JSONWidget, NamedTypeWidget, NillableWidget []ent.Interceptor
	}
)
